async function bf58Environment(){
 const {localEnvironment}=await import('../../scripts/enterprise/local.mjs'),{login}=await import('./http-helper.mjs'),{scope,operations}=await import('../../scripts/enterprise/fixture.mjs');
 const env=await localEnvironment(),records=[],checks=[],migrations=[];
 const api=async(user,operation,body={},key)=>{const r=await user.api(operation,body,key),x={operation,request:body,key,status:r.status,body:await r.json()};records.push(x);return x;};
 const ok=async(...args)=>{const r=await api(...args);assert.equal(r.status,200,JSON.stringify(r));return r.body.result;};
 try{
 const users={};for(const who of ['operator','manager','reviewer','publisher','other','tenant2'])users[who]=await login(env,who);
 const b=env.f.create({id:'bf58-case'});await ok(users.operator,'create',b);
 for(const version of ['2.0.0','3.0.0']){const manifest=structuredClone(env.f.manifest);manifest.version=version;manifest.calendar.businessDays=Number(version[0])+2;await ok(users.manager,'install',{manifest});await ok(users.reviewer,'review',{id:manifest.id,version});await ok(users.publisher,'publish',{id:manifest.id,version});}
 const snapshot=async()=>{const state={};for(const [table,order]of [['objects','id'],['actions','id'],['enterprise_instances','id'],['history','object_id,revision'],['outbox','operation_id'],['enterprise_packages','tenant,id,version']])state[table]=(await env.f.owner.query(`SELECT * FROM ${table} ORDER BY ${order}`)).rows;return {state,journal:env.f.kernel.journal.records(),requests:env.effects.requests(),ledger:await env.effects.ledger()};};
 const migrate=async(version,revision)=>{const body={id:b.id,version,revision},key=crypto.randomUUID(),result=await ok(users.publisher,'definitionMigrate',body,key);const action=(await env.f.owner.query("SELECT * FROM actions WHERE request->>'key'=$1",[key])).rows[0];migrations.push({body,key,result,action});return result;};
 await migrate('2.0.0',1);await migrate('3.0.0',2);await migrate('1.0.0',3);
 const exportCheck=async(user=users.manager,body={id:b.id},status=200)=>{const before=await snapshot(),audit=(await env.f.owner.query('SELECT * FROM audit ORDER BY sequence')).rows,r=await api(user,'auditExport',body),after=await snapshot();checks.push({before,after,response:r});assert.deepEqual(after,before);assert.deepEqual((await env.f.owner.query('SELECT * FROM audit WHERE sequence<=$1 ORDER BY sequence',[audit.at(-1).sequence])).rows,audit);assert.equal(r.status,status);return r;};
 const clean=report=>{const found=report.events.filter(x=>x.record.operation==='definitionMigrate'&&!x.record.bf58Fixture);assert.deepEqual(found.map(x=>x.record.actionId),migrations.map(x=>x.action.id),'successful migration audit missing');for(const [n,e]of found.entries()){const m=migrations[n];assert.equal(e.record.operationId,m.action.operation_id);assert.deepEqual(e.record.resource,{namespace:'enterprise-case',tenant:'t1',kind:'Case',id:b.id});assert.deepEqual(e.definitionMigration,{packageId:b.packageId,from:{version:m.result.from,digest:report.events.find(x=>x.record.operation==='install'&&x.definitionVersion?.version===m.result.from)?.definitionVersion.digest},to:{version:m.result.version,digest:report.events.find(x=>x.record.operation==='install'&&x.definitionVersion?.version===m.result.version)?.definitionVersion.digest},revision:m.result.revision});assert.ok(e.definitionMigration.from.digest);assert.ok(e.definitionMigration.to.digest);}
 for(const version of ['1.0.0','2.0.0','3.0.0'])for(const op of ['install','review','publish'])assert.ok(report.events.some(x=>x.record.operation===op&&x.definitionVersion?.version===version),'definition lineage missing '+op+' '+version);
 assert.equal(report.definition.version,'1.0.0');assert.equal(JSON.stringify(report).includes(b.fields.memo),false);return found;};
 return {env,users,b,api,ok,snapshot,migrations,exportCheck,clean,records,checks,scope,operations};
 }catch(e){await env.close();throw e;}
}

