 const collision={...structuredClone(env.f.manifest),id:b.id};await ok(users.manager,'install',{manifest:collision});await ok(users.reviewer,'review',{id:b.id,version:collision.version});await ok(users.publisher,'publish',{id:b.id,version:collision.version});
