 const schema=(await env.f.owner.query('SELECT current_schema() name')).rows[0].name,args=['-h',env.cluster.config.host,'-p',String(env.cluster.config.port),'-U',env.cluster.config.user,'-d',env.cluster.config.database];
 const dump=name=>{const file=env.cluster.directory+'/'+name+'.sql';execFileSync('pg_dump',[...args,'--schema='+schema,'--file='+file]);return file;};const restore=async file=>{await env.f.owner.query(`DROP SCHEMA ${schema} CASCADE`);execFileSync('psql',[...args,'--single-transaction','--set=ON_ERROR_STOP=1','--file='+file],{stdio:'pipe'});};
 const reconnect=async()=>{await env.gateway.close();restart(env.f);env.gateway=await enterpriseGateway(env.f.kernel,{issuer:env.idp.issuer});for(const who of ['manager','publisher'])users[who]=await login(env,who);};
 const oldUser=users.manager,stable=dump('bf58-stable');await reconnect();clean((await exportCheck()).body.result);await restore(stable);await reconnect();clean((await exportCheck()).body.result);
 const fields=['PUBLIC','INTERNAL','CONFIDENTIAL','STRICT','RESTRICTED'],grant=(scopes=[scope],ops=operations,labels=fields)=>ok(users.publisher,'grant',{principal:'manager',scopes,operations:ops,fields:labels});
 await grant([]);await exportCheck(users.manager,{id:b.id},404);await grant([scope],operations.filter(x=>x!=='audit'));await exportCheck(users.manager,{id:b.id},403);await grant();
